"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "Ce qui est débarrassé du bourdonnement : la prise, ou un fichier fait à partir d'elle qui n'est ni débourdonné ni suréchantillonné.",
"Strength": "Force",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "Quelle part de l'ondulation des trames retirer par division. L'oreille de Viktor : 100 % amincissait l'ouverture, 80 % était juste.",
"Which file is measured: the take, or any file made from it.": "Quel fichier est mesuré : la prise, ou tout fichier fait à partir d'elle.",
"Inspect": "Inspecter",
"Where the sound sits: spectrogram, average spectrum, band energy. Lay another take over it to compare.": "Où se situe le son : spectrogramme, spectre moyen, énergie par bande. Superpose une autre prise pour comparer.",
"Log": "Log",
"Linear": "Linéaire",
"Lays a second spectrum under this one, on the same scale: a file made from this take, or another take.": "Pose un second spectre sous celui-ci, à la même échelle : un fichier fait à partir de cette prise, ou une autre prise.",
"Compare with": "Comparer avec",
"Full screen: zoom and scroll (or double-click the picture). A click plays from there when this take is in the player.": "Plein écran : zoom et défilement (ou double-clic sur l'image). Un clic lit depuis là quand cette prise est dans le lecteur.",
"Full screen: zoom and scroll": "Plein écran : zoom et défilement",
"Whisper listens to this take on Forge and matches what it hears to your lyrics, minute by minute.": "Whisper écoute cette prise sur Forge et compare ce qu'il entend à tes paroles, minute par minute.",
"What Whisper listens to": "Ce que Whisper écoute",
"The take as it is, or a stem of it: on the vocal stem Whisper hears the words without the music": "La prise telle quelle, ou l'un de ses stems : sur le stem de voix, Whisper entend les mots sans la musique",
"Listen with Whisper": "Écouter avec Whisper",
"Karaoke timing": "Synchronisation karaoké",
"Time the lines": "Caler les lignes",
"Made from this take": "Fait à partir de cette prise",
"Made from This Take": "Fait à partir de Cette Prise",
