"The ticked ones, or with none ticked the whole trash: deleted for good, with everything made from them. Asks first.": "Celles qui sont cochées, ou si rien n'est coché toute la corbeille : supprimées pour de bon, avec tout ce qui en a été fait. Demande d'abord.",
