"Which rank, how many steps, the other knobs: the guide": "Quel rang, combien de pas, les autres réglages : le guide",
"How to choose ›": "Comment choisir ›",
"How big each step is. Keep the kind's own; higher learns faster and forgets more.": "La taille de chaque pas. Garde celle du type ; plus haut apprend plus vite et oublie davantage.",
"Learning rate": "Taux d'apprentissage",
"AR weight": "Poids AR",
"0 = sound only": "0 = son seulement",
"Holds the music half near the base model, so it keeps what it was not shown; higher holds tighter.": "Maintient la moitié musique près du modèle de base, pour qu'elle garde ce qu'on ne lui a pas montré ; plus haut maintient plus fort.",
