"Delete non-favourites…": "Supprimer les non-favoris…",
"Search · * and ? work": "Recherche · * et ? marchent",
"Finds takes here by title or library name: * stands for any letters, ? for one. The column's filters still apply.": "Trouve les prises ici par titre ou nom dans la bibliothèque : * remplace n'importe quelles lettres, ? une seule. Les filtres de la colonne s'appliquent toujours.",
"Keep as a favourite": "Garder comme favori",
