"The log to the left side of the page, kept for this room": "Le journal sur le côté gauche de la page, gardé pour cette salle",
"The log to the left side of the page": "Le journal sur le côté gauche de la page",
"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "L'ampleur du changement de l'adaptateur : 16 pour une voix ou un instrument, 32 pour un style, 64 pour de nombreuses voix, 128 au plus.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "Si la moitié musique apprend (la partie qui écrit les tokens de la chanson), et avec quelle force sa leçon tire contre l'ancre : 0 la laisse comme la base, un timbre seulement ; monte-le pour la diction et le style. Ce qui compte, c'est la part de l'ancre, pas sa taille.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "Ramène la moitié musique vers le modèle de base, pour qu'elle garde ce que l'ensemble ne montre pas. Lis-le comme une part du poids AR : un dixième la laisse bouger, autant que le poids la tient près de la base. Rien avec un poids AR à 0.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "Le taux d'apprentissage de la moitié musique en part de celui du dessus : le réglage qui la fait apprendre plus vite ou plus lentement (0.5 : deux fois moins vite). Elle apprend vite par cœur un petit ensemble.",
"How they work ›": "Comment ils marchent ›",
"The music half's three knobs: the guide": "Les trois réglages de la moitié musique : le guide",
