"Out of the studio": "Hors du studio",
"two ways: the mixed track as it is, or the whole take into your DAW, where the rest happens outside the studio": "deux chemins : la piste mixée telle quelle, ou la prise entière dans ta DAW, où le reste se fait hors du studio",
"The mixed track": "La piste mixée",
"As the studio made it (and the Refiner finished it), no DAW in between.": "Telle que le studio l'a faite (et l'Affineur finie), sans DAW entre les deux.",
"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "Telle que le studio l'a faite (et l'Affineur finie), sans DAW entre les deux. Prise en main :",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Ouvre une prise, joue-en une ou coche-en une dans le Bibliothécaire : ses WAV, FLAC et MP3 arrivent ici.",
"Into your DAW": "Dans ta DAW",
"experimental": "expérimental",
"It works and was checked, but it still needs crash tests on other machines and projects, and more work": "Ça marche et c'est vérifié, mais il faut encore des tests de résistance sur d'autres machines et projets, et plus de travail",
"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "La prise entière comme projet de ta DAW : les stems sur leurs pistes, la partition en MIDI, le tempo, les sections en régions, les paroles sur la timeline. Quelle DAW utilises-tu ?",
