"The title, style and lyrics there now are replaced. They are in no document: “Save to Writer” first, if they matter.": "Le titre, le style et les paroles qui y sont maintenant sont remplacés. Ils ne sont dans aucun document : « Enregistrer dans l'Écrivain » d'abord, s'ils comptent.",
