"All the music strengths together. Measured on this studio's takes: the score came out whole up to {0} in every run, broken from 2.5 in every run. Green to {1}, amber to {2}, red past it.": "Toutes les forces de musique ensemble. Mesuré sur les prises de ce studio : la partition est sortie entière jusqu'à {0} à chaque exécution, cassée dès 2.5 à chaque exécution. Vert jusqu'à {1}, ambre jusqu'à {2}, rouge au-delà.",
