"No LoRAs found. Put .safetensors files (or folders, or links to them) in the app's loras/ folder.": "Aucun LoRA trouvé. Mets des fichiers .safetensors (ou des dossiers, ou des liens vers eux) dans le dossier loras/ de l'app.",
"{0} is no longer in loras/ and will be left out.": "{0} n'est plus dans loras/ et sera laissé de côté.",
