"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0} : {1} sur la moitié musique dépasse sa limite {2} : la partition tend à échouer après 70-200 jetons.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0} : {1} sur la moitié son dépasse sa limite {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} planifie des partitions instrumentales : à {1} avec des paroles à chanter, la partition perd sa ligne vocale (mesuré à 1.00 : 1 note en 127 mesures vocales, la musique en boucle). Garde-le bas, 0.3–0.5, pour une chanson chantée.",
"{#0} stacked: their changes add up.": "{#0} empilés : leurs changements s'additionnent.",
"⚠ The music half carries {0} together, past the shared ceiling {1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ La moitié musique porte {0} ensemble, au-delà du plafond commun {1} : des exécutions aussi lourdes ont écrit des partitions cassées à chaque fois (mesuré). Baisse-en quelques-uns, ou retires-en un de la moitié musique.",
