"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "Style et paroles ensemble : environ {#0} jetons sur {#1} — trop long pour une chanson et une partition complètes.",
"Unlike the model's training styles:": "Contrairement aux styles d'entraînement du modèle :",
"longer than 1,600 characters (the official examples stop at 999)": "plus de 1 600 caractères (les exemples officiels s'arrêtent à 999)",
"{#0} Unicode arrow (→): write -> instead": "{#0} flèche Unicode (→) : écris -> à la place",
"{#0} Unicode arrows (→): write -> instead": "{#0} flèches Unicode (→) : écris -> à la place",
"dynamics marks (never in the official styles)": "marques de nuances (jamais dans les styles officiels)",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "{#0} champs « Label: » (5 des 110 styles officiels en utilisent)",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{#0} ligne entre crochets dans les paroles avec un « Label: », une flèche ou une marque p/f (aucune dans les exemples officiels)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{#0} lignes entre crochets dans les paroles avec un « Label: », une flèche ou une marque p/f (aucune dans les exemples officiels)",
"{#0} instruments": {"one": "{#0} instrument", "other": "{#0} instruments"},
"{#0} heard": "entendus : {#0}",
"{#0} questioned": "mis en doute : {#0}",
"{#0} not identified": "non identifiés : {#0}",
"{#0} not judged yet": "pas encore jugés : {#0}",
"the Librarian does not answer: no probes to play": "le Bibliothécaire ne répond pas : aucune sonde à jouer",
"{#0} styles": {"one": "{#0} style", "other": "{#0} styles"},
"{#0} style": {"one": "{#0} style", "other": "{#0} styles"},
"what a probe gave instead of its instrument": "ce qu'une sonde a donné à la place de son instrument",
"Nothing matches.": "Rien ne correspond.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Un nom dans le style est une demande, pas une promesse. Ce que jouent ▶ A et ▶ B, c'est ce que YuE2 donne pour lui, environ neuf fois sur dix.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Certaines sondes sont superbes, et A et B s'accordent, pourtant l'instrument n'est pas celui demandé : fie-toi à l'oreille, pas au nom.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Ce qu'on a demandé à YuE2 de jouer, un instrument ou un style à la fois, en sondes de deux minutes (une minute pour les premières), deux graines chacune, A et B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Un instrument façonne le style de tout le morceau : en nommer un change aussi l'arrangement. Un craquement ou un froissement de papier, comme sur un disque usé, c'est une graine malchanceuse : refais-la avec une autre.",
