"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "Restaurer ramène la copie publiée sur Hugging Face : les prises qui lui manquent reviennent, les titres et les notes reprennent ceux publiés, et ce qui y a été ajouté quitte l'espace (ces prises restent dans la bibliothèque ; ses propres sections restent). Pour garder le tien tel quel : Annuler, renomme ton espace (le ⋯ à côté de son nom, puis Renommer…), et Récupérer à nouveau : l'original arrive à côté sous son propre nom.",
