"The phonetic hand: stress marks (U+0301), ayins inside Russian words (a soft о/а), Latin letters inside Russian words (a hard o)": "La main phonétique : accents toniques (U+0301), aïns dans les mots russes (un о/а doux), lettres latines dans les mots russes (un o dur)",
