"Look up on Civitai": "Rechercher sur Civitai",
"Each adapter not yet known looked up on civitai.com by its SHA-256 alone: its name, its base model and its trigger words kept beside it (NAME.civitai.info), with its first picture rated safe when it has none": "Chaque adaptateur pas encore connu recherché sur civitai.com par son seul SHA-256 : son nom, son modèle de base et ses mots déclencheurs gardés à côté de lui (NAME.civitai.info), avec sa première image classée sûre quand il n'en a pas",
