"Put .safetensors files into the studio's artwork/loras/{0}/ folder: any folders inside it become groups here; a picture beside a file with its name (NAME.jpg, NAME.png, NAME.preview.png) shows on its card.": "Mets des fichiers .safetensors dans le dossier artwork/loras/{0}/ du studio : les dossiers dedans deviennent des groupes ici ; une image à côté d'un fichier avec son nom (NAME.jpg, NAME.png, NAME.preview.png) s'affiche sur sa carte.",
"On Civitai, pick adapters by their base model ({0}), download the .safetensors and put it there; Look up on Civitai then fills in its name and its trigger words.": "Sur Civitai, choisis les adaptateurs par leur modèle de base ({0}), télécharge le .safetensors et mets-le là ; Rechercher sur Civitai remplit ensuite son nom et ses mots déclencheurs.",
