"pictures for your songs from a prompt of your own: square, wide and tall from one seed, painted by Krea 2 Muse or Qwen-Image": "des images pour tes chansons à partir d'un prompt à toi : carrées, larges et hautes depuis une graine, peintes par Krea 2 Muse ou Qwen-Image",
"what to paint, said in sentences (Krea 2 and Qwen-Image read them); Ctrl+Enter draws": "quoi peindre, dit en phrases (Krea 2 et Qwen-Image les lisent) ; Ctrl+Entrée dessine",
