"All the sound strengths together. By ear (05.10.2026): two adapters at sound 1.0 each, 2.0 together, brought a heavy bass; 0.55 together sounded right. Green to 1, amber to 1.5, red past it. Drag it to move them all at once, each in proportion.": "Toutes les forces de son ensemble. À l'oreille (05.10.2026) : deux adaptateurs au son 1.0 chacun, 2.0 ensemble, ont amené une basse lourde ; 0.55 ensemble sonnait juste. Vert jusqu'à 1, ambre jusqu'à 1.5, rouge au-delà. Fais-le glisser pour les déplacer tous à la fois, chacun en proportion.",
