"Tick what to look for. A take is shown when it has all of the ticked (AND), any of them (OR) or none of them (NOR); the numbers count the takes of this place.": "Coche ce qu'il faut chercher. Une prise s'affiche quand elle a tout ce qui est coché (AND), au moins une chose (OR) ou rien de tout cela (NOR) ; les nombres comptent les prises de cet endroit.",
