"M-A-P's YuE2 as GGUF": "YuE2 de M-A-P en GGUF",
"the whole model; on a card older than Ampere (an RTX 20xx, a Quadro RTX) it runs without its tensor cores, slower than Q8_0": "le modèle entier ; sur une carte plus ancienne qu'Ampere (une RTX 20xx, une Quadro RTX) il tourne sans ses cœurs tensoriels, plus lentement que Q8_0",
"The whole model; on a card older than Ampere (an RTX 20xx, a Quadro RTX) it runs without its tensor cores, slower than Q8_0": "Le modèle entier ; sur une carte plus ancienne qu'Ampere (une RTX 20xx, une Quadro RTX) il tourne sans ses cœurs tensoriels, plus lentement que Q8_0",
"Style listener": "Écouteur de style",
"Qwen2.5-Omni-7B: hears the songs of a training set and writes each one's style tags; the GGUF ones run through llama.cpp (vendor/llama.cpp, built by you)": "Qwen2.5-Omni-7B : écoute les chansons d'un jeu d'entraînement et écrit les tags de style de chacune ; ceux en GGUF tournent via llama.cpp (vendor/llama.cpp, compilé par toi)",
"The style listener: Qwen2.5-Omni-7B ({0})": "L'écouteur de style : Qwen2.5-Omni-7B ({0})",
"{#0} GB of VRAM when it listens": "{#0} Go de VRAM quand il écoute",
"{#0} GB of VRAM when it listens: a 24 GB card": "{#0} Go de VRAM quand il écoute : une carte de 24 Go",
"the Artist's painter: Krea 2 Muse by Stable Yogi with Krea 2's text encoder and VAE, the content filter its licence asks for, and the prompt writer (Qwen3-4B)": "le peintre du Peintre : Krea 2 Muse de Stable Yogi avec l'encodeur de texte et le VAE de Krea 2, le filtre de contenu que sa licence demande, et le rédacteur de prompts (Qwen3-4B)",
"the Artist's painter (no card here has the 16 GB Krea 2 wants): SDXL CyberRealistic, and the prompt writer (Qwen3-4B)": "le peintre du Peintre (aucune carte ici n'a les 16 Go que veut Krea 2) : SDXL CyberRealistic, et le rédacteur de prompts (Qwen3-4B)",
