"Qwen painters": "Peintres Qwen",
"the Artist's Qwen-Image painters: 2512 with Lightning's 8 steps (Apache-2.0: its parts from Qwen, the transformer as GGUF) and 2.1 (Qwen's research licence)": "les peintres Qwen-Image du Peintre : 2512 avec les 8 étapes de Lightning (Apache-2.0 : ses parties de Qwen, le transformeur en GGUF) et 2.1 (licence de recherche de Qwen)",
"the Artist's Qwen-Image painters": "les peintres Qwen-Image du Peintre",
"for a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "pour une carte de 16 Go (sous 20 Go son encodeur de texte lit le prompt sur le processeur : 17 Go de RAM) ; une demi-minute par image sur une 3090 ; moins quand une partie est déjà ici",
"For a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "Pour une carte de 16 Go (sous 20 Go son encodeur de texte lit le prompt sur le processeur : 17 Go de RAM) ; une demi-minute par image sur une 3090 ; moins quand une partie est déjà ici",
"For a card of 24 GB; less when some of it is here": "Pour une carte de 24 Go ; moins quand une partie est déjà ici",
"Under Qwen's research licence: research and evaluation only, not for commercial use (a cover for a song that is sold is commercial use); a card of 24 GB, about two minutes a picture": "Sous la licence de recherche de Qwen : recherche et évaluation seulement, pas d'usage commercial (une pochette pour une chanson vendue est un usage commercial) ; une carte de 24 Go, environ deux minutes par image",
"LoRA trainer's base": "Base de l'entraîneur LoRA",
"Comfy-Org/YuE2 for the Trainer, with Mothersuperior's tokenizer head and m-a-p's MERT-v2-FullSong (the set's latent cache hears with it)": "Comfy-Org/YuE2 pour l'Entraîneur, avec la tête de tokenizer de Mothersuperior et MERT-v2-FullSong de m-a-p (le cache latent du jeu écoute avec lui)",
"Trains on unquantized weights; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "S'entraîne sur des poids non quantifiés ; les 2,5 Go de MERT-v2-FullSong en font partie, moins quand il est déjà ici",
"For a smaller card; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "Pour une carte plus petite ; les 2,5 Go de MERT-v2-FullSong en font partie, moins quand il est déjà ici",
