"{0} cannot move there": "{0} ne peut pas aller là",
"The same disk: the folder is renamed there at once, nothing is copied.": "Le même disque : le dossier y est renommé aussitôt, rien n'est copié.",
"Another disk: {0} copied (free there: {1}), checked file by file, then the link switched. The old copy stays, renamed, until you remove it.": "Un autre disque : {0} copiés (libre là-bas : {1}), vérifiés fichier par fichier, puis le lien changé. L'ancienne copie reste, renommée, jusqu'à ce que tu la supprimes.",
