"The sound decoder for the songs to come. A take already made decodes again with another one from its card, in seconds.\n\nStandard · the cleanest sound, the newer model, the default\nLegacy · the older official decoder, the benchmarks were made with it\nBlend · an add-on: two thirds Standard, one third Legacy": "Le décodeur du son pour les chansons à venir. Une prise déjà faite se décode à nouveau avec un autre depuis sa carte, en quelques secondes.\n\nStandard · le son le plus propre, le modèle le plus récent, par défaut\nLegacy · l'ancien décodeur officiel, les benchmarks ont été faits avec lui\nMélange · un module : deux tiers Standard, un tiers Legacy",
