"Put a plain .txt (UTF-8) in place of the lyrics: asked first when the box has words; Ctrl+Z in the box brings them back": "Mettre un simple .txt (UTF-8) à la place des paroles : demandé d'abord quand le champ contient des mots ; Ctrl+Z dans le champ les ramène",
