"The whole page's text smaller or larger (−2 to +4 pt): the layout stays; a lifted frame has its own on top": "Tout le texte de la page plus petit ou plus grand (−2 à +4 pt) : la mise en page reste ; un cadre détaché a le sien par-dessus",
"Keys": "Touches",
"Line numbers": "Numéros de ligne",
"The lines' numbers in the box, as a code editor shows them (Alt+K marks a line, Alt+J goes to the next mark)": "Les numéros des lignes dans le champ, comme un éditeur de code les montre (Alt+K marque une ligne, Alt+J va à la marque suivante)",
"Marks: {0}": "Marques : {0}",
"Marked lines: Alt+K marks the cursor's line or unmarks it, Alt+J goes to the next, Alt+Shift+J to the one before, Alt+Shift+K clears them. Press to go to the next one.": "Lignes marquées : Alt+K marque la ligne du curseur ou la démarque, Alt+J va à la suivante, Alt+Shift+J à la précédente, Alt+Shift+K les efface. Appuie pour aller à la suivante.",
"Press to go to the next one.": "Appuie pour aller à la suivante.",
"line {0}: {1}": "ligne {0} : {1}",
"Tags not closed or astray: {0}": "Balises non fermées ou égarées : {0}",
"Round brackets to look at: {0}": "Parenthèses à regarder : {0}",
"Stress marks off a vowel: {0}": "Accents toniques hors d'une voyelle : {0}",
"Words with two stress marks: {0}": "Mots avec deux accents toniques : {0}",
"A stress mark (U+0301) stands right after the vowel it stresses. Press to go to the next one.": "Un accent tonique (U+0301) se place juste après la voyelle qu'il accentue. Appuie pour aller au suivant.",
"One word, two stress marks: meant, or a slip? Press to go to the next one.": "Un mot, deux accents toniques : voulu, ou une faute ? Appuie pour aller au suivant.",
"{0} is a spacing accent, not the stress mark (U+0301 after the vowel)": "{0} est un accent avec espacement, pas l'accent tonique (U+0301 après la voyelle)",
"at the line's start": "au début de la ligne",
"(before {0})": "(avant {0})",
"after a space": "après une espace",
"a second mark on {0}": "une deuxième marque sur {0}",
"on {0}, not a vowel": "sur {0}, pas une voyelle",
"after {0}": "après {0}",
"two marks in {0}": "deux marques dans {0}",
"Consonant beats: {0}": "Temps consonantiques : {0}",
"Beats no vowel carries, counted with the syllables in each line's bar (drawn lighter): a word with no vowel (с, в, к, з, й, ў) and a stop closed against an affricate inside a word (глу-п-цо́в)": "Des temps qu'aucune voyelle ne porte, comptés avec les syllabes dans la barre de chaque ligne (dessinés plus clairs) : un mot sans voyelle (с, в, к, з, й, ў) et une occlusive fermée contre une affriquée dans un mot (глу-п-цо́в)",
"The lyrics editor's keys, as in mcedit:\nAlt+K  mark the cursor's line (again: unmark it)\nAlt+J  the next mark · Alt+Shift+J the one before\nAlt+O  clear the marks (Alt+Shift+K too)\nAlt+L  go to a line by its number\nCtrl+Y  delete the line\nAlt+↑ Alt+↓  move the line, or the lines selected\n[ at a line's start, or Ctrl+Space  the section tags\nCtrl+F  find in the box\nAlt+I  the instruments' and styles' cheat-sheet\nCtrl+Z  take a change back": "Les touches de l'éditeur de paroles, comme dans mcedit :\nAlt+K  marquer la ligne du curseur (encore : la démarquer)\nAlt+J  la marque suivante · Alt+Shift+J la précédente\nAlt+O  effacer les marques (Alt+Shift+K aussi)\nAlt+L  aller à une ligne par son numéro\nCtrl+Y  supprimer la ligne\nAlt+↑ Alt+↓  déplacer la ligne, ou les lignes sélectionnées\n[ en début de ligne, ou Ctrl+Espace  les balises de section\nCtrl+F  chercher dans le champ\nAlt+I  l'aide-mémoire des instruments et des styles\nCtrl+Z  annuler une modification",
"Already in the lyrics, line {0}: a song has one": "Déjà dans les paroles, ligne {0} : une chanson en a une",
"The lyrics number their verses: this is the next one": "Les paroles numérotent leurs couplets : voici le suivant",
"{0} times in the 110 official examples": "{0} fois dans les 110 exemples officiels",
"{#0} times in the 110 official examples": {"one": "{#0} fois dans les 110 exemples officiels", "other": "{#0} fois dans les 110 exemples officiels"},
"already at line {0}": "déjà à la ligne {0}",
"the next verse": "le couplet suivant",
"↑ ↓ choose · Enter or Tab puts it in · Esc closes": "↑ ↓ choisir · Entrée ou Tab l'insère · Échap ferme",
"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "TEST : aucun des 110 exemples officiels ne l'écrit, donc YuE2 peut le chanter comme des mots ou le passer. Écoute avant de le garder.",
"{0} replaced": "{0} remplacés",
