"Male vocals in the Style: a click puts them there (in place of female ones); a click on the lit one takes their tag out": "Voix masculine dans le Style : un clic l'y met (à la place de la féminine) ; un clic sur celle qui est allumée retire son tag",
"Female vocals in the Style: a click puts them there (in place of male ones); a click on the lit one takes their tag out": "Voix féminine dans le Style : un clic l'y met (à la place de la masculine) ; un clic sur celle qui est allumée retire son tag",
"Clear the music seed: every run picks a random one again": "Effacer la graine de la musique : chaque exécution en tire une au hasard à nouveau",
"Clear the sound seed: every run picks a random one again": "Effacer la graine du son : chaque exécution en tire une au hasard à nouveau",
"Render this take's sound again with this VAE: it was made before takes kept their latents, so it takes as long as its sound did\n{0}": "Refaire le son de cette prise avec ce VAE : elle a été faite avant que les prises gardent leurs latents, donc cela prend autant de temps que son son a pris\n{0}",
"Decode this take again with this VAE: its own sound, another decoder, in seconds\n{0}": "Décoder à nouveau cette prise avec ce VAE : son propre son, un autre décodeur, en quelques secondes\n{0}",
