"This version\n{0}": "Cette version\n{0}",
"Sound seed {#0}\nsame music, another grain": "Graine du son {#0}\nmême musique, autre grain",
"None on this server. Start it with --sliders to add voice and genre sliders.": "Aucun sur ce serveur. Lance-le avec --sliders pour ajouter les curseurs de voix et de genre.",
"{#0} decoders · {1} picked in the ☰ menu · a finished song can add another from its page": "{#0} décodeurs · {1} choisi dans le menu ☰ · une chanson finie peut en ajouter un autre depuis sa page",
