"Between the sections a vocalise an octave up, written into the lyrics as «(Ooh, aah)», instead of a bar's rest": "Entre les sections une vocalise une octave plus haut, écrite dans les paroles comme « (Ooh, aah) », au lieu d'une mesure de silence",
"The take in hand out of the studio: the mixed track as it is, or the whole take into your DAW (with its stems, once they are split here)": "La prise en main hors du studio : la piste mixée telle quelle, ou la prise entière dans ta DAW (avec ses stems, une fois séparés ici)",
