"AITK": "AITK",
"Ruach": "Ruach",
"AI-Toolkit": "AI-Toolkit",
"EN": "EN",
"RU": "RU",
"JSON": "JSON",
"TXT": "TXT",
"ABC": "ABC",
"mp3": "mp3",
"End at…": "Finir à…",
"End the take at a moment: its last 2 s fade out, and nothing after it is kept. For a song that runs on past its proper end (in Full, the score's leftover bars after the last words). The moment is where the player stands when this take plays; otherwise you are asked. From the take's kept latents in seconds (the very sound), else its music codes rendered again. A new take; this one stays.": "Finir la prise à un moment : ses 2 dernières s s'éteignent en fondu, et rien après n'est gardé. Pour une chanson qui continue après sa vraie fin (en Complet, les mesures restantes de la partition après les derniers mots). Le moment est là où se trouve le lecteur quand cette prise joue ; sinon on te le demande. À partir des latents gardés de la prise en quelques secondes (le son même), sinon ses codes musicaux rendus à nouveau. Une nouvelle prise ; celle-ci reste.",
"Fade in…": "Fondu d'entrée…",
"Fade the take in: its first seconds rise from silence (2 s unless you say otherwise), for a song that starts too abruptly. From the take's kept latents in seconds (the very sound), else its music codes rendered again. A new take; this one stays.": "Faire entrer la prise en fondu : ses premières secondes montent du silence (2 s sauf si tu dis autrement), pour une chanson qui commence trop brusquement. À partir des latents gardés de la prise en quelques secondes (le son même), sinon ses codes musicaux rendus à nouveau. Une nouvelle prise ; celle-ci reste.",
"Loop…": "Boucle…",
"A loop from this take: 1, 2, 4 or 8 bars on its score's bar lines, from the bar where the player stands (else the first), seamless (its end runs into its start), saved as a WAV named with its tempo and key": "Une boucle à partir de cette prise : 1, 2, 4 ou 8 mesures sur les barres de mesure de sa partition, depuis la mesure où se trouve le lecteur (sinon la première), sans couture (sa fin rejoint son début), enregistrée en WAV nommé avec son tempo et sa tonalité",
"On 15 s": "Avancer de 15 s",
"Back 15 s": "Reculer de 15 s",
"On to the next quarter-minute mark. The → key: to the next 5 s mark": "Vers le prochain quart de minute. La touche → : vers la prochaine marque de 5 s",
"A sound when a run ends": "Un son quand une exécution finit",
"A sound when a run made here ends: two notes up when it is done (a queue of runs once, when its last one ends), two down when one fails. None over a new song that starts playing by itself; as loud as the player. Click to make none.": "Un son quand une exécution lancée ici finit : deux notes montantes quand elle est terminée (une file d'exécutions une seule fois, quand sa dernière finit), deux descendantes quand une échoue. Rien par-dessus une nouvelle chanson qui démarre toute seule ; aussi fort que le lecteur. Clique pour n'en avoir aucun.",
"Count again": "Recompter",
"Count the folders' files and sizes again": "Recompter les fichiers et les tailles des dossiers",
"Scan the machine": "Analyser la machine",
"What this machine has, and what suits it: the backbone, the context and the VAE tiles, the painter": "Ce que cette machine a, et ce qui lui convient : le backbone, le contexte et les tuiles VAE, le peintre",
"Check again": "Vérifier à nouveau",
"Compare what is here with the pinned lists again; nothing is downloaded": "Comparer à nouveau ce qui est ici avec les listes épinglées ; rien n'est téléchargé",
"Restart the engine": "Redémarrer le moteur",
"The engine reads its backbones, decoders and sliders when it starts": "Le moteur lit ses backbones, décodeurs et curseurs au démarrage",
"Folders": "Dossiers",
"What the studio downloads beside itself: the decoders and the sliders, Whisper, the stems' models, UniverSR and the LoRAs, which the install brings, and the extras you ask for. Each file comes from Hugging Face at the revision the release pins and is checked against its size; a download cut short goes on where it stopped. Nothing is downloaded until you press Fetch.": "Ce que le studio télécharge à côté de lui : les décodeurs et les curseurs, Whisper, les modèles des stems, UniverSR et les LoRA, que l'installation apporte, et les extras que tu demandes. Chaque fichier vient de Hugging Face à la révision que la version épingle et est vérifié par sa taille ; un téléchargement interrompu reprend là où il s'est arrêté. Rien n'est téléchargé tant que tu n'appuies pas sur Récupérer.",
"Where your work lives: the songs (with the workspaces fetched from Hugging Face), the trash, the Artist's pictures and the Writer's documents. Each may live on any disk: the studio's folder then holds a link to it, and everything reads it there as before. The models, the LoRAs and the training sets keep their places.": "Là où vit ton travail : les chansons (avec les espaces récupérés sur Hugging Face), la corbeille, les images du Peintre et les documents de l'Écrivain. Chacun peut vivre sur n'importe quel disque : le dossier du studio contient alors un lien vers lui, et tout le lit là comme avant. Les modèles, les LoRA et les jeux d'entraînement gardent leur place.",
