"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: whole context, VAE tiles {#2})": "Auto ({#0} Go trouvés, sa limite {#1} Go dans Moteur → GPU : tout le contexte, tuiles VAE {#2})",
"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: too small for YuE2)": "Auto ({#0} Go trouvés, sa limite {#1} Go dans Moteur → GPU : trop peu pour YuE2)",
"The most of the card’s memory the studio’s work may take, the rest left to what else runs on it (a laptop’s desktop and browser): Compute’s Auto plans the engine’s knobs for the studio card’s limit, and the lab gives a card a job only when it fits under its limit": "Le maximum de la mémoire de la carte que le travail du studio peut prendre, le reste laissé à ce qui tourne d'autre dessus (le bureau et le navigateur d'un portable) : l'Auto de Calcul règle les boutons du moteur pour la limite de la carte du studio, et le labo ne donne une tâche à une carte que si elle tient sous sa limite",
