"The Artist's own log: what was asked, what the lab answered, each run's way to its end; kept in this browser": "Le journal propre du Peintre : ce qui a été demandé, ce que le labo a répondu, le chemin de chaque exécution jusqu'à sa fin ; gardé dans ce navigateur",
