"Replace all (Ctrl+Enter)": "Tout remplacer (Ctrl+Entrée)",
"Replace the match in hand and go on to the next (Enter)": "Remplacer la correspondance en main et passer à la suivante (Entrée)",
"Replace every match at once (Ctrl+Enter); one Ctrl+Z in the box takes it all back": "Remplacer toutes les correspondances d'un coup (Ctrl+Entrée) ; un seul Ctrl+Z dans le champ annule tout",
