"the official examples counted": "les exemples officiels comptés",
"it goes onto the clipboard and, where you say, into the Style prompt; a name the Style holds already is marked; a lyrics tag goes onto the clipboard only": "il va dans le presse-papiers et, là où tu le dis, dans le prompt Style ; un nom que le Style contient déjà est marqué ; une balise de paroles va seulement dans le presse-papiers",
"The clipboard did not take it": "Le presse-papiers ne l'a pas pris",
"Russian · conservative (Viktor's)": "Russe · conservateur (de Viktor)",
"The Artist's log": "Le journal du Peintre",
"Transcribed {0} in {1}. Check the melody under Supply your own score, then write the new lyrics and style.": "{0} transcrit en {1}. Vérifie la mélodie sous Fournir ta propre partition, puis écris les nouvelles paroles et le style.",
"1 take carries a score you can remix.": "1 prise porte une partition que tu peux remixer.",
"{#0} takes carry a score you can remix.": {"one": "{#0} prise porte une partition que tu peux remixer.", "other": "{#0} prises portent une partition que tu peux remixer."},
"Make a song in Full plan or Melody only mode first; Direct mode keeps no score.": "Fais d'abord une chanson en mode Plan complet ou Mélodie seule ; le mode Direct ne garde pas de partition.",
"A reference is a PNG, JPEG or WebP picture": "Une référence est une image PNG, JPEG ou WebP",
"The picture could not be read": "L'image n'a pas pu être lue",
"Pick a take on the right first": "Choisis d'abord une prise à droite",
"The prompt its artwork was drawn from": "Le prompt à partir duquel son illustration a été dessinée",
"A prompt from its title and style: say more of what you see": "Un prompt à partir de son titre et de son style : dis-en plus sur ce que tu vois",
"Put the take's prompt in place of the one written here?": "Mettre le prompt de la prise à la place de celui écrit ici ?",
"What is written now goes; each run below keeps its own prompt.": "Ce qui est écrit maintenant s'en va ; chaque exécution ci-dessous garde son propre prompt.",
"Put it in": "Le mettre",
"Pick a take with a cover on the right first": "Choisis d'abord une prise avec une pochette à droite",
"Back among the runs": "Retour parmi les exécutions",
"The upscaler": "L'agrandisseur",
