"TTA: each tile through the upscaler in its eight orientations (four turns, each mirrored), averaged: steadier edges and textures, up to eight times the time (Upscayl's way)": "TTA : chaque tuile passe par l'agrandisseur dans ses huit orientations (quatre rotations, chacune en miroir), moyennées : bords et textures plus stables, jusqu'à huit fois le temps (à la manière d'Upscayl)",
