"Unload model: {0} GB in the card’s memory now (busy: it waits), and the Artist’s painter kept between runs on GPU {1}": "Décharger le modèle : {0} Go dans la mémoire de la carte maintenant (occupé : il attend), et le peintre du Peintre gardé entre les exécutions sur le GPU {1}",
