"Spectrum over the wave": "Spectre au-dessus de l'onde",
"Spectrum over the wave: the pointer on the wave brings the whole take's spectrogram up over the player, as wide as the wave, the section's words above it. Click to turn it off.": "Spectre au-dessus de l'onde : le pointeur sur l'onde fait monter au-dessus du lecteur le spectrogramme de toute la prise, aussi large que l'onde, les paroles de la section au-dessus. Clique pour le désactiver.",
