"RMS: how loud each moment is, in dBFS, in the lane at the foot; the dashed line is the take's own average": "RMS : le volume de chaque instant, en dBFS, sur la bande du bas ; la ligne pointillée est la moyenne propre de la prise",
"Frequency scale": "Échelle des fréquences",
"The frequencies on a log scale, as the ear hears them: each octave as tall as the next": "Les fréquences sur une échelle logarithmique, comme l'oreille les entend : chaque octave aussi haute que la suivante",
"The frequencies on a linear scale: the highs wide, the lows packed at the foot": "Les fréquences sur une échelle linéaire : les aigus larges, les graves tassés en bas",
