"A second pass, as Viktor's ComfyUI workflow makes it: the picture brought up 1.5 or 2 times and painted over by its own painter, adapters, prompt and seed, with the form's steps and sampler; a run of its own": "Une seconde passe, comme la fait le workflow ComfyUI de Viktor : l'image agrandie 1.5 ou 2 fois et repeinte par son propre peintre, ses adaptateurs, son prompt et sa graine, avec les pas et l'échantillonneur du formulaire ; une exécution à part",
"Second pass…": "Seconde passe…",
"How much the second pass may change the picture: 0.3 keeps its drawing and adds detail, 0.5 sharpens its matter, 0.7 repaints its forms": "Combien la seconde passe peut changer l'image : 0.3 garde son dessin et ajoute du détail, 0.5 affine sa matière, 0.7 repeint ses formes",
"Second pass asked:": "Seconde passe demandée :",
"The second pass ×{0} waits for a card with room, then paints the picture over": "La seconde passe ×{0} attend une carte avec de la place, puis repeint l'image",
"No second pass: {0}": "Pas de seconde passe : {0}",
"second pass ×{0}": "seconde passe ×{0}",
"Extra noise": "Bruit ajouté",
"Fresh noise added to the picture before it is painted from, as Viktor's ComfyUI workflow does (InjectLatentNoise): 0 none, 0.3 new grain and detail, 0.6 his second pass, above 1 the picture's forms begin to break": "Du bruit frais ajouté à l'image avant de peindre à partir d'elle, comme le fait le workflow ComfyUI de Viktor (InjectLatentNoise) : 0 aucun, 0.3 du grain et du détail nouveaux, 0.6 sa seconde passe, au-delà de 1 les formes de l'image commencent à se défaire",
"extra noise {0}": "bruit ajouté {0}",
"Regions": "Régions",
"Up to three parts of the frame, each with words of its own: at every step the painter is asked once more for each region, with the prompt and the region's words, and the answers are blended by soft-edged boxes (Latent Couple's way). Each region costs a whole pass more a step. Krea 2 and Qwen-Image 2512": "Jusqu'à trois parties du cadre, chacune avec ses propres mots : à chaque pas, le peintre est interrogé une fois de plus pour chaque région, avec le prompt et les mots de la région, et les réponses se mêlent par des cadres aux bords doux (à la manière de Latent Couple). Chaque région coûte une passe entière de plus par pas. Krea 2 et Qwen-Image 2512",
"Add a region": "Ajouter une région",
"Not with Qwen-Image 2.1: it edits by words": "Pas avec Qwen-Image 2.1 : elle modifie par les mots",
