"to paint from": "pour peindre à partir d'elle",
"to edit by words (Qwen-Image 2.1)": "pour la modifier par les mots (Qwen-Image 2.1)",
"for its style only (Qwen-Image 2.1)": "pour son style seulement (Qwen-Image 2.1)",
"How the picture is used: painted from (image to image, by the form's painter, as far as How much it may change says); edited by the prompt's words (Qwen-Image 2.1 keeps the scene and changes what the words say); or for its style only (Qwen-Image 2.1 paints the prompt's own scene in the picture's technique, brushwork, palette and light). Qwen-Image 2.1 is under the Qwen Research Licence: research and evaluation only": "Comment l'image sert : peindre à partir d'elle (image to image, par le peintre du formulaire, aussi loin que le dit Combien elle peut changer) ; la modifier par les mots du prompt (Qwen-Image 2.1 garde la scène et change ce que disent les mots) ; ou son style seulement (Qwen-Image 2.1 peint la scène du prompt avec la technique, la touche, la palette et la lumière de l'image). Qwen-Image 2.1 est sous la Qwen Research Licence : recherche et évaluation seulement",
"in the picture's style": "dans le style de l'image",
"edited by words": "modifiée par les mots",
"The answer reached the output limit: review it carefully, or raise Max tokens.": "La réponse a atteint la limite de sortie : relis-la avec soin, ou augmente « Tokens max ».",
"The model gave an empty answer: nothing came back from {0}.": "Le modèle a donné une réponse vide : rien n'est venu de {0}.",
"It may have spent the whole answer on its thinking, or stopped at once. Send it again, raise Max tokens, or pick another model.": "Il a peut-être dépensé toute la réponse à réfléchir, ou s'est arrêté aussitôt. Renvoie-la, augmente « Tokens max » ou choisis un autre modèle.",
